import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас данных', quotaUsed: 42, status: 'active' },
  { id: 'p2', name: 'Портал клиентов', quotaUsed: 88, status: 'over' },
  { id: 'p3', name: 'Внутренняя аналитика', quotaUsed: 15, status: 'paused' },
  { id: 'p4', name: 'Мобильное приложение', quotaUsed: 67, status: 'active' },
  { id: 'p5', name: 'Биллинг', quotaUsed: 100, status: 'over' },
  { id: 'p6', name: 'Служба поддержки', quotaUsed: 30, status: 'active' },
  { id: 'p7', name: 'Архив документов', quotaUsed: 5, status: 'paused' },
  { id: 'p8', name: 'Публичный API', quotaUsed: 74, status: 'active' },
  { id: 'p9', name: 'Отчётность', quotaUsed: 95, status: 'over' },
  { id: 'p10', name: 'Интеграции', quotaUsed: 20, status: 'paused' },
  { id: 'p11', name: 'Личный кабинет', quotaUsed: 55, status: 'active' },
  { id: 'p12', name: 'Резервное копирование', quotaUsed: 12, status: 'paused' },
];

const statusOptions: Array<{ value: ProjectStatus; label: string; tone: 'success' | 'warning' | 'danger' }> = [
  { value: 'active', label: 'Активен', tone: 'success' },
  { value: 'paused', label: 'На паузе', tone: 'warning' },
  { value: 'over', label: 'Превышена квота', tone: 'danger' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(
    statusOptions.map((option) => option.value),
  );
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((value) => value !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusOptions.map((option) => option.value));
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  const statusMeta = (status: ProjectStatus) =>
    statusOptions.find((option) => option.value === status)!;

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        padding: 'var(--jx-r)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {statusOptions.map((option) => {
          const isActive = activeStatuses.includes(option.value);
          return (
            <JxChip
              key={option.value}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(option.value)}
              onClick={() => {
                if (!isActive) {
                  toggleStatus(option.value);
                }
              }}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          message="Снимите часть фильтров или сбросьте их, чтобы увидеть все проекты."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => {
              const meta = statusMeta(project.status);
              return (
                <div
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 'var(--jx-r)',
                    padding: '12px',
                    borderBottom: '1px solid var(--jx-rule)',
                  }}
                >
                  <span
                    style={{
                      color: 'var(--jx-text)',
                      fontWeight: 500,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      flex: '1 1 auto',
                      minWidth: 0,
                    }}
                  >
                    {project.name}
                  </span>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '16px', flexShrink: 0 }}>
                    <JxProgressCircle value={project.quotaUsed} showValue />
                    <JxBadge tone={meta.tone}>{meta.label}</JxBadge>
                  </div>
                </div>
              );
            })}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

